import type React from 'react';

export const isMac = () => navigator.platform.toUpperCase().includes('MAC');

type CombinedKeyboardEvent = KeyboardEvent | React.KeyboardEvent;
type CombinedMouseEvent = MouseEvent | React.MouseEvent;

export const isEnter = (event: CombinedKeyboardEvent) =>
    event.code === 'Enter' || event.code === 'NumpadEnter' || event.key === 'Enter';
export const isSpace = (event: CombinedKeyboardEvent) => event.code === 'Space';
export const isEscape = (event: CombinedKeyboardEvent) => event.code === 'Escape';
export const isTab = (event: CombinedKeyboardEvent) => event.code === 'Tab';
export const isHome = (event: CombinedKeyboardEvent) => event.code === 'Home';
export const isEnd = (event: CombinedKeyboardEvent) => event.code === 'End';

export const isArrowUp = (event: CombinedKeyboardEvent) => event.code === 'ArrowUp';
export const isArrowDown = (event: CombinedKeyboardEvent) => event.code === 'ArrowDown';

export const hasMetaKey = (event: CombinedKeyboardEvent | CombinedMouseEvent) =>
    event.ctrlKey || event.metaKey;
export const hasModKey = (event: CombinedKeyboardEvent | CombinedMouseEvent) =>
    isMac() ? hasMetaKey(event) : event.altKey;
export const isCtrlZ = (event: CombinedKeyboardEvent) => hasMetaKey(event) && event.code === 'KeyZ';
export const isSubmitHotkey = (event: CombinedKeyboardEvent) => isEnter(event) && hasMetaKey(event);
